def per_doc_auroc(scores, z, doc_of, n_docs):
    """A5 alternative: AUROC computed inside each document, then averaged over the
    documents that contain both classes.  Documents with no anomalous token have an
    undefined AUROC and are skipped."""
    per = []
    for d in range(n_docs):
        m = doc_of == d
        if m.sum() == 0 or len(np.unique(z[m])) < 2:
            continue
        per.append(auroc(z[m], scores[m]))
    return {"n_docs_scored": len(per), "mean": float(np.mean(per)) if per else float("nan"),
            "std": float(np.std(per)) if per else float("nan")}


